# -*- coding: utf-8 -*-
"""miner_1 2028-03-23: explore novel factor batch.
Visible data through 2028-03-22. Gates: |IC| >= 0.007 and |ICIR| >= 0.084 at 10d
horizon on the 15-asset universe; post-gate max_abs_library_correlation < 0.5.
Existing library covers: trend quality, semi-deviation, plain momentum 10/120d,
time-under-water, vol-of-vol, DXY/WTI/VIX betas, kurtosis, tail ratio.
This batch targets ORTHOGONAL ideas:
  1. Volume dynamics: vol_trend_20, vol_z_20, amihud_20 (illiquidity)
  2. Vol term-structure / range: hv_ratio_10_60, parkinson_ratio_20, range_pct_20
  3. Lottery/extreme: max_ret_20, min_ret_20, up_capture_20
  4. Cross-asset conditional: xau_beta_60, copper_beta_60, spx_corr_60,
     cn10y_beta_60, eq_rel_mom_20 (relative momentum vs equity complex)
  5. Volume-confirmed momentum: mom20_vol_confirm (momentum x volume expansion)
"""
import sys, json, os, math
import numpy as np
import pandas as pd
sys.path.insert(0, 'scripts')
import miner3_lib as L

# refresh library factor list from live factor files (EFFECTIVE + artifact)
lib_factors = []
for p in sorted(os.listdir('factors')):
    if not p.endswith('.json') or p == 'factor_ensemble.json':
        continue
    try:
        d = json.load(open('factors/' + p))
        if d.get('validation', {}).get('status') == 'EFFECTIVE' and \
           d.get('validation', {}).get('signal_artifact'):
            lib_factors.append(d['factor_id'])
    except Exception:
        pass
L.LIB_FACTORS = lib_factors
print('Library factors for rho check (%d): %s' % (len(lib_factors), lib_factors))

C, V, H, Lw, O = L.load_close_panel(4000)
R = C.pct_change()
print('Panel: %s -> %s | %d dates x %d assets' % (C.index.min().date(), C.index.max().date(), len(C), C.shape[1]))

def safe_div(a, b):
    return (a / b).replace([np.inf, -np.inf], np.nan)

def build(name):
    # ---- 1. Volume dynamics ----
    if name == 'vol_trend_20':
        # 20d avg volume vs 60d avg volume: volume expansion/contraction
        return safe_div(V.rolling(20).mean(), V.rolling(60).mean())
    if name == 'vol_z_20':
        # current volume z-score vs trailing 60d volume distribution
        mu = V.rolling(60).mean()
        sd = V.rolling(60).std()
        return safe_div(V - mu, sd)
    if name == 'amihud_20':
        # Amihud illiquidity: mean(|ret| / dollar-vol proxy) over 20d
        illiq = safe_div(R.abs(), V)
        return illiq.rolling(20).mean()
    # ---- 2. Vol term-structure / range ----
    if name == 'hv_ratio_10_60':
        # short-term vol vs long-term vol (vol term structure)
        return safe_div(R.rolling(10).std(), R.rolling(60).std())
    if name == 'parkinson_ratio_20':
        # Parkinson vol (intraday range-based) vs close-to-close vol
        hl = (H / Lw).apply(np.log)
        park = hl.rolling(20).std() * math.sqrt(1 / (4 * math.log(2)))
        c2c = R.rolling(20).std()
        return safe_div(park, c2c)
    if name == 'range_pct_20':
        # average daily range as % of close (volatility level)
        rng = safe_div(H - Lw, C)
        return rng.rolling(20).mean()
    # ---- 3. Lottery / extremes ----
    if name == 'max_ret_20':
        # max 1d return over 20d (lottery demand)
        return R.rolling(20).max()
    if name == 'min_ret_20':
        # min 1d return over 20d (crash sensitivity)
        return R.rolling(20).min()
    if name == 'up_capture_20':
        # upside days avg / downside days avg (return asymmetry)
        up = R.where(R > 0).rolling(20).mean()
        dn = R.where(R < 0).rolling(20).mean()
        return safe_div(up, dn.abs())
    # ---- 4. Cross-asset conditional ----
    if name == 'xau_beta_60':
        f = R['XAU']
        return safe_div(R.rolling(60).cov(f), f.rolling(60).var())
    if name == 'copper_beta_60':
        f = R['COPPER']
        return safe_div(R.rolling(60).cov(f), f.rolling(60).var())
    if name == 'spx_corr_60':
        # rolling 60d correlation to SPX (systematic linkage)
        f = R['SPX']
        return R.rolling(60).corr(f)
    if name == 'cn10y_beta_60':
        f = R['CN10Y']
        return safe_div(R.rolling(60).cov(f), f.rolling(60).var())
    if name == 'eq_rel_mom_20':
        # own 20d momentum minus equal-weight equity-complex 20d momentum
        eq = C[['SPX', 'HSI', 'N225', 'SX5E', '000300.SH', '000688.SH', 'SOX', 'NDX']]
        eq_mom = eq.pct_change(20).mean(axis=1)
        own = C.pct_change(20)
        return (own.sub(eq_mom, axis=0)).replace([np.inf, -np.inf], np.nan)
    # ---- 5. Volume-confirmed momentum ----
    if name == 'mom20_vol_confirm':
        # 20d momentum scaled by volume expansion (volume-confirmed trend)
        mom20 = C.pct_change(20)
        vexp = safe_div(V.rolling(20).mean(), V.rolling(60).mean())
        return (mom20 * vexp).replace([np.inf, -np.inf], np.nan)
    return None

CANDIDATES = ['vol_trend_20', 'vol_z_20', 'amihud_20',
              'hv_ratio_10_60', 'parkinson_ratio_20', 'range_pct_20',
              'max_ret_20', 'min_ret_20', 'up_capture_20',
              'xau_beta_60', 'copper_beta_60', 'spx_corr_60',
              'cn10y_beta_60', 'eq_rel_mom_20', 'mom20_vol_confirm']

out = {'visible_through': str(C.index.max().date()), 'n_dates': len(C), 'n_assets': C.shape[1],
       'library_factors': lib_factors, 'results': {}}
for name in CANDIDATES:
    fp = build(name)
    if fp is None:
        print('\n[%s] build failed' % name)
        continue
    try:
        summ = L.full_validate(fp, R, horizon=10, label=name)
    except Exception as e:
        print('\n[%s] validation error: %s' % (name, e))
        continue
    gate_ic = abs(summ['ic']) >= 0.007
    gate_icir = abs(summ['icir']) >= 0.084
    maxrho = summ['max_abs_library_correlation']
    rho_ok = maxrho < 0.5
    out['results'][name] = {k: summ[k] for k in
                            ['label', 'horizon', 'ic', 'icir', 'ic_hit_ratio', 'n_ic_dates',
                             'regime', 'coverage_asset_days', 'coverage_dates_ge8',
                             'turnover_10d_rank', 'decay_ic_by_horizon',
                             'max_abs_library_correlation']}
    print('\n=== %s ===' % name)
    print('  IC=%.4f ICIR=%.4f hit=%.3f n=%d cov_asset=%.3f cov_dates_ge8=%.3f turn=%.3f'
          % (summ['ic'], summ['icir'], summ['ic_hit_ratio'], summ['n_ic_dates'],
             summ['coverage_asset_days'], summ['coverage_dates_ge8'], summ['turnover_10d_rank']))
    print('  decay:', summ['decay_ic_by_horizon'])
    print('  regime:', {k: v['ic'] for k, v in summ.get('regime', {}).items()})
    print('  max_abs_library_corr=%.3f' % maxrho)
    print('  GATE PASS(ic/icir): %s  rho_ok=%s' % (gate_ic and gate_icir, rho_ok))

with open('scripts/miner_1_20280323_explore_results.json', 'w') as f:
    json.dump(out, f, indent=1, default=str)
print('\nSaved results to scripts/miner_1_20280323_explore_results.json')

