    return df


def load_macro(sym):
    df = pd.read_csv(os.path.join(INDEX_DIR, f"{sym}.csv"))
    df["date"] = pd.to_datetime(df["date"])
    df = df[df["date"] <= VISIBLE_THROUGH].sort_values("date").reset_index(drop=True)
    return df


