import numpy as np
import pandas as pd

VISIBLE_THROUGH = "2032-04-28"
CURRENT_DATE = "2032-04-29"

IC_THRESHOLD = 0.0070
ICIR_THRESHOLD = 0.0840

WATCH = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX",
