        return None
    ic = float(ics.mean())
    icir = float(ics.mean() / ics.std()) if ics.std() > 0 else 0.0
    hit = float((ics > 0).mean())
    print(f"[{label}] horizon={horizon}d n={len(ics)} IC={ic:.4f} ICIR={icir:.4f} hit={hit:.3f}")
