def lib_trend_r2(close, window=30):
    lc = np.log(close)
    t = np.arange(len(close), dtype=float)
    r2 = {}
    for c in close.columns:
        y = lc[c]
        beta = y.rolling(window).cov(pd.Series(t, index=y.index)) / pd.Series(t, index=y.index).rolling(window).var()
        alpha = y - beta * t
        fit = alpha + beta * t
        ss_res = ((y - fit) ** 2).rolling(window).mean()
        ss_tot = ((y - y.rolling(window).mean()) ** 2).rolling(window).mean()
        r2[c] = 1 - ss_res / ss_tot
    r2df = pd.DataFrame(r2)
    return r2df * np.sign(beta)


